import json
import collections

# Retrieve parameters
map_id = input_data['map_id']
start_x = int(input_data['start_x'])
start_y = int(input_data['start_y'])
target_x = int(input_data['target_x'])
target_y = int(input_data['target_y'])

def find_path():
    max_x, max_y = 100, 100
    if map_id == "0_219":
        max_x, max_y = 30, 22
    elif map_id == "0_218":
        max_x, max_y = 40, 36
    elif map_id == "0_217":
        max_x, max_y = 30, 22
    elif map_id == "0_220":
        max_x, max_y = 30, 27

    impassable = set()

    if map_id == "0_219":
        # Eastern tree wall
        for y in range(1, 13):
            impassable.add((24, y))
        # Western blocks
        for y in [14, 15]:
            impassable.add((1, y))
        impassable.add((0, 16))
        # Water on row 13
        for x in [2, 3, 4, 5, 6, 7, 8]:
            impassable.add((x, 13))
        # Solid tree walls / boundaries
        for x in range(30):
            impassable.add((x, 21)) # bottom border
            impassable.add((x, 0)) # top border
        for y in range(22):
            impassable.add((0, y))
            impassable.add((29, y))

    # Stairs definitions: (stairs_x, stairs_y) -> (top_plateau_x, top_plateau_y, bottom_ground_x, bottom_ground_y)
    stairs = {}
    if map_id == "0_219":
        stairs[(21, 17)] = ((21, 16), (21, 18))
        stairs[(6, 19)] = ((6, 18), (6, 20))
    elif map_id == "0_218":
        stairs[(34, 15)] = ((34, 14), (34, 16))
        stairs[(28, 27)] = ((28, 26), (28, 28))
        stairs[(22, 23)] = ((22, 22), (22, 24))
        stairs[(16, 27)] = ((16, 26), (16, 28))
    elif map_id == "0_217":
        stairs[(20, 21)] = ((20, 20), (20, 22))
        stairs[(12, 7)] = ((12, 6), (12, 8))
        stairs[(17, 7)] = ((17, 6), (17, 8))
        stairs[(11, 20)] = ((11, 19), (11, 21))

    # Helper to check if a tile is on the plateau
    def is_plateau_tile(x, y):
        if map_id == "0_219":
            if 5 <= x <= 11 and 13 <= y <= 18:
                return True
            if 12 <= x <= 22 and 14 <= y <= 16:
                return True
            if 12 <= x <= 16 and y == 17:
                return True
        elif map_id == "0_218":
            if 18 <= x <= 24 and 20 <= y <= 22:
                return True
            if 13 <= x <= 17 and 24 <= y <= 26:
                return True
            if 25 <= x <= 29 and 24 <= y <= 26:
                return True
            if 31 <= x <= 35 and 12 <= y <= 14:
                return True
        elif map_id == "0_217":
            if 11 <= x <= 22 and 5 <= y <= 6:
                return True
            if 11 <= x <= 22 and 7 <= y <= 19:
                return True
            if 11 <= x <= 22 and 20 <= y <= 20:
                return True
        return False

    if is_plateau_tile(start_x, start_y):
        start_elv = "plateau"
    else:
        start_elv = "ground"

    # BFS state: (x, y, elevation, path)
    queue = collections.deque([(start_x, start_y, start_elv, [])])
    visited = set([(start_x, start_y, start_elv)])

    while queue:
        cx, cy, celv, path = queue.popleft()

        target_elv = "plateau" if is_plateau_tile(target_x, target_y) else "ground"
        if (cx, cy) == (target_x, target_y) and celv == target_elv:
            return path

        for dx, dy, move in [(0, -1, "Up"), (0, 1, "Down"), (-1, 0, "Left"), (1, 0, "Right")]:
            nx, ny = cx + dx, cy + dy

            if not (0 <= nx < max_x and 0 <= ny < max_y):
                continue
            if (nx, ny) in impassable:
                continue

            nelv = celv

            if (nx, ny) in stairs:
                top, bottom = stairs[(nx, ny)]
                if celv == "ground" and (cx, cy) == bottom:
                    pass
                elif celv == "plateau" and (cx, cy) == top:
                    pass
                else:
                    continue

            elif (cx, cy) in stairs:
                top, bottom = stairs[(cx, cy)]
                if celv == "ground" and (nx, ny) == top:
                    nelv = "plateau"
                elif celv == "plateau" and (nx, ny) == bottom:
                    nelv = "ground"
                elif celv == "ground" and (nx, ny) == bottom:
                    pass
                elif celv == "plateau" and (nx, ny) == top:
                    pass
                else:
                    continue

            else:
                next_is_plat = is_plateau_tile(nx, ny)
                if celv == "plateau" and not next_is_plat:
                    continue
                if celv == "ground" and next_is_plat:
                    continue

            state = (nx, ny, nelv)
            if state not in visited:
                visited.add(state)
                queue.append((nx, ny, nelv, path + [move]))

    return None

path = find_path()
if path is not None:
    print(json.dumps(path))
else:
    print(json.dumps([]))
